// ---- B. link branches with rs == $31 -----------------------------
//
// `taken` and `delay_ran` are what the console did; `links` says the
// form writes $31 at all. The captured $ra was an address inside the
// probe ELF, so the portable fact carried forward is that a linking
// form left pc+8 there -- asserted by the test, not stored here.
struct BranchCase
{
	const char* label;
	int op;        // index into the encoder switch
	u64 ra_in;
	bool taken;
	bool delay_ran;
	bool links;
	bool likely;
};

